          <<"\x18", 0::1, varint_value::7, rest::binary>> ->
            value = varint_value
            msg = %{msg | storageQuotaMb: value}
            parse_key_value(rest, msg)

          <<"\x18", bytes::binary>> ->
            {value, rest} = Protox.Decode.parse_uint32(bytes)
